    const auto& point = points[i];

    if (point.x >= range.Min.x && point.x <= range.Max.x &&
        point.y >= range.Min.y && point.y <= range.Max.y &&
        point.z >= range.Min.z && point.z <= range.Max.z) {
        result.push_back(i);
    }
}

